# -------------------- Load saved artifacts --------------------
@st.cache_resource
def load_artifacts():
    if not os.path.exists(MODEL_PATH):
        raise FileNotFoundError(f"Missing model file: {MODEL_PATH}")
    if not os.path.exists(VECTORIZER_PATH):
        raise FileNotFoundError(f"Missing vectorizer file: {VECTORIZER_PATH}")
    with open(MODEL_PATH, "rb") as f:
        model = pickle.load(f)
    with open(VECTORIZER_PATH, "rb") as f:
        vectorizer = pickle.load(f)

    label_map = DEFAULT_LABEL_MAP.copy()
    if os.path.exists(MAPPING_PATH):
        import json
        with open(MAPPING_PATH, "r", encoding="utf-8") as f:
            loaded_map = json.load(f)
        label_map = {int(key): str(value).strip().lower() for key, value in loaded_map.items()}

    # Catch a mismatched model/vectorizer pair before inference.
    model_features = getattr(model, "n_features_in_", None)
    vectorizer_features = len(getattr(vectorizer, "vocabulary_", {}))
    if model_features is not None and model_features != vectorizer_features:
        raise ValueError(
            f"Model/vectorizer mismatch: model expects {model_features} features, "
            f"but vectorizer creates {vectorizer_features}. Use the matching files "
            "saved from the same notebook run."
        )
    return model, vectorizer, label_map

def clean_text(text):
    """
    Match the notebook's preprocessing order:
    lowercase -> remove punctuation -> remove digits -> remove non-ASCII
    -> remove NLTK English stopwords.
    """
    import string

    text = text.lower()
    text = text.translate(str.maketrans("", "", string.punctuation))

    cleaned = ""
    for char in text:
        if not char.isdigit():
            cleaned += char

    text = "".join(char for char in cleaned if char.isascii())

    try:
        from nltk.corpus import stopwords
        stop_words = set(stopwords.words("english"))
    except (ImportError, LookupError) as exc:
        raise RuntimeError(
            "This model was trained with NLTK English stopwords. "
            "Install NLTK and run `python -m nltk.downloader stopwords` "
            "so the app uses the same preprocessing as the notebook."
        ) from exc

    tokens = [word for word in text.split() if word not in stop_words]
    return " ".join(tokens)


def normalize_label(label, label_map=None):
    """Convert numeric model classes or text labels into emotion names."""
    try:
        numeric = int(label)
        if str(label).strip() == str(numeric):
            active_map = label_map or DEFAULT_LABEL_MAP
            if numeric in active_map:
                return active_map[numeric]
    except (TypeError, ValueError):
        pass
    return str(label).strip().lower()

def get_emotion_info(label, label_map=None):
    key = normalize_label(label, label_map)
    return EMOTIONS.get(key, {
        "label": str(label).title(), "color": "#B18CFF",
        "description": "Emotion predicted by the trained model",
        "image": "fear.png"
    })

def show_emotion_image(filename, width=90):
    path = os.path.join(ASSET_DIR, filename)
    if os.path.exists(path):
        st.image(path, width=width)

